//! Inputs for the TOML benchmarks.

/// A Cargo.lock-shaped document with `n` packages.
pub fn lockfile(n: usize) -> String {
    let mut s = String::from(
        "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n",
    );
    for i in 0..n {
        s.push_str(&format!(
            "\n[[package]]\nname = \"package-{i}\"\nversion = \"{}.{}.{}\"\nsource = \"registry+https://github.com/rust-lang/crates.io-index\"\nchecksum = \"{:064x}\"\n",
            i % 7, i % 13, i % 29, (i as u128).wrapping_mul(0x9e37_79b9_7f4a_7c15_f39c_c060_5ced_c834)
        ));
        if i % 3 != 0 {
            s.push_str("dependencies = [\n");
            for d in 0..(i % 5 + 1) {
                s.push_str(&format!(" \"package-{}\",\n", (i * 7 + d) % n.max(1)));
            }
            s.push_str("]\n");
        }
    }
    s
}

/// A document with every kind of value, about `kib` KiB.
pub fn mixed(kib: usize) -> String {
    let mut s = String::from("title = \"A mixed document\"\n");
    let mut i = 0;
    while s.len() < kib * 1024 {
        s.push_str(&format!(
            "\n[section-{i}]\n\
             name = \"entry {i} with \\\"escapes\\\" and \\u00e9\"\n\
             literal = 'C:\\path\\{i}'\n\
             count = {}\n\
             ratio = {}.{}\n\
             big = 1_000_{:03}\n\
             enabled = {}\n\
             when = 2026-11-{:02}T{:02}:30:00Z\n\
             tags = [\"a\", \"b\", \"c-{i}\"]\n\
             point = {{ x = {i}, y = -{i}, label = \"p{i}\" }}\n\
             nested.deep.value = {i}\n\
             text = \"\"\"\nline one\nline two {i}\n\"\"\"\n\
             [[section-{i}.items]]\nid = {i}\n\
             [[section-{i}.items]]\nid = {}\n",
            i * 37,
            i,
            i % 100,
            i % 1000,
            i % 2 == 0,
            i % 28 + 1,
            i % 24,
            i + 1
        ));
        i += 1;
    }
    s
}

